mapper.insert:
		/*
             SQL ID : SmnrFdbkDAO.smnrFdbkRegist
             설  명 : 세미나피드백등록
         */
        INSERT INTO TB_LMS_SMNR_FDBK (
        	  SMNR_FDBK_ID
			, SMNR_ID
			, USER_ID
			, FDBK_CTS
			, RGTR_ID
			, REG_DTTM
        ) VALUES (
        	  #{smnrFdbkId}
			, #{smnrId}
			, #{userId}
			, #{fdbkCts}
			, #{rgtrId}
			, FN_DTTM()
        )

		/*
             SQL ID : SmnrFdbkDAO.smnrFdbkBulkRegist
             설  명 : 세미나피드백일괄등록
         */
        INSERT ALL

			INTO TB_LMS_SMNR_FDBK (
	         	  SMNR_FDBK_ID
				, SMNR_ID
				, USER_ID
				, FDBK_CTS
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.smnrFdbkId}
				, #{item.smnrId}
				, #{item.userId}
				, #{item.fdbkCts}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.update:
		/*
             SQL ID : SmnrFdbkDAO.smnrFdbkDelete
             설  명 : 세미나피드백삭제
         */
        UPDATE TB_LMS_SMNR_FDBK SET
        	  DELYN = 'Y'
        	, MDFR_ID = #{mdfrId}
        	, MOD_DTTM = FN_DTTM()
         WHERE SMNR_FDBK_ID = #{smnrFdbkId}
